window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-113e5ae0d191d2da"]={"versions": [{"id": "FIG-113e5ae0d191d2da", "releases": ["R17-10_R1.2.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Kommunikationsspezifikationen auf der Empfängerseite (<code>ClientComSpec</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die strukturelle Einbettung von Port-Kommunikationsspezifikationen für clientseitige Interaktionen über Service-Schnittstellen (Operations und Fields).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Aggregiert über eine Komposition mit Rolle <code>+requiredComSpec</code> beliebig viele Instanzen von <code>RPortComSpec</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>RPortComSpec</code> (kursiv/abstrakt): Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.</li>\n<li><code>ClientComSpec</code>: Spezialisierung von <code>RPortComSpec</code>.</li>\n<li>Attribut: <code>clientCapability: ClientCapabilityEnum [0..1]</code>.</li>\n<li>Assoziation zu <code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>): Rolle <code>+operation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Assoziationen zu <code>Field</code> (Spezialisierung von <code>AutosarDataPrototype</code>):</li>\n<li>Rolle <code>+getter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+setter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Komposition zu <code>TransformationComSpecProps</code> (Spezialisierung von <code>Describable</code>): Rolle <code>+transformationComSpecProps</code>, Multiplizität <code>0..*</code>.</li>\n<li><code>ClientServerOperation</code>:</li>\n<li>Attribut: <code>fireAndForget: Boolean [0..1]</code>.</li>\n<li><code>Field</code>:</li>\n<li>Attribute: <code>hasGetter: Boolean</code>, <code>hasNotifier: Boolean</code>, <code>hasSetter: Boolean</code>.</li>\n<li><code>ClientCapabilityEnum</code> («enumeration»):</li>\n<li>Literale: <code>willCall</code>, <code>wontCall</code>.</li>\n<li><code>TransformationComSpecProps</code>: Abstrakter bzw. allgemeiner Eigenschaftscontainer für transformationsspezifische Konfigurationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Spezifikation definiert Konfigurationsartefakte zur Design- und Generierungszeit: <code>ClientComSpec</code> deklariert die Client-Absicht bzw. -Fähigkeit bezüglich des Aufrufs von Operationen sowie der Getter- und Setter-Methoden von Fields (<code>willCall</code>/<code>wontCall</code>) und konfiguriert optional Fire-and-Forget-Semantik sowie transformationsbezogene Kommunikationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von Manifesten auf der Adaptive Platform müssen sicherstellen, dass bei Zuweisung einer <code>ClientComSpec</code> zu einem <code>AbstractRequiredPortPrototype</code> die referenzierten Operationen oder Field-Accessor-Methoden (<code>+getter</code>, <code>+setter</code>) konsistent zu den Service-Interface-Definitionen modelliert sind. <code>clientCapability</code> steuert die Optimierung und Codegenerierung bezüglich tatsächlicher Aufrufe.</p>"}, {"id": "FIG-bb6b3cfcb85a396b", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Kommunikationsspezifikationen auf der Empfängerseite (<code>ClientComSpec</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die strukturelle Einbettung von Port-Kommunikationsspezifikationen für clientseitige Interaktionen über Service-Schnittstellen (Operations und Fields).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Aggregiert über eine Komposition mit Rolle <code>+requiredComSpec</code> beliebig viele Instanzen von <code>RPortComSpec</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>RPortComSpec</code> (kursiv/abstrakt): Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.</li>\n<li><code>ClientComSpec</code>: Spezialisierung von <code>RPortComSpec</code>.</li>\n<li>Attribut: <code>clientCapability: ClientCapabilityEnum [0..1]</code>.</li>\n<li>Assoziation zu <code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>): Rolle <code>+operation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Assoziationen zu <code>Field</code> (Spezialisierung von <code>AutosarDataPrototype</code>):</li>\n<li>Rolle <code>+getter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+setter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Komposition zu <code>TransformationComSpecProps</code> (Spezialisierung von <code>Describable</code>): Rolle <code>+transformationComSpecProps</code>, Multiplizität <code>0..*</code>.</li>\n<li><code>ClientServerOperation</code>:</li>\n<li>Attribut: <code>fireAndForget: Boolean [0..1]</code>.</li>\n<li><code>Field</code>:</li>\n<li>Attribute: <code>hasGetter: Boolean</code>, <code>hasNotifier: Boolean</code>, <code>hasSetter: Boolean</code>.</li>\n<li><code>ClientCapabilityEnum</code> («enumeration»):</li>\n<li>Literale: <code>willCall</code>, <code>wontCall</code>.</li>\n<li><code>TransformationComSpecProps</code>: Abstrakter bzw. allgemeiner Eigenschaftscontainer für transformationsspezifische Konfigurationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Spezifikation definiert Konfigurationsartefakte zur Design- und Generierungszeit: <code>ClientComSpec</code> deklariert die Client-Absicht bzw. -Fähigkeit bezüglich des Aufrufs von Operationen sowie der Getter- und Setter-Methoden von Fields (<code>willCall</code>/<code>wontCall</code>) und konfiguriert optional Fire-and-Forget-Semantik sowie transformationsbezogene Kommunikationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von Manifesten auf der Adaptive Platform müssen sicherstellen, dass bei Zuweisung einer <code>ClientComSpec</code> zu einem <code>AbstractRequiredPortPrototype</code> die referenzierten Operationen oder Field-Accessor-Methoden (<code>+getter</code>, <code>+setter</code>) konsistent zu den Service-Interface-Definitionen modelliert sind. <code>clientCapability</code> steuert die Optimierung und Codegenerierung bezüglich tatsächlicher Aufrufe.</p>"}, {"id": "FIG-b5a60ae4c9d07f88", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Kommunikationsspezifikationen auf der Empfängerseite (<code>ClientComSpec</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die strukturelle Einbettung von Port-Kommunikationsspezifikationen für clientseitige Interaktionen über Service-Schnittstellen (Operations und Fields).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Aggregiert über eine Komposition mit Rolle <code>+requiredComSpec</code> beliebig viele Instanzen von <code>RPortComSpec</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>RPortComSpec</code> (kursiv/abstrakt): Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.</li>\n<li><code>ClientComSpec</code>: Spezialisierung von <code>RPortComSpec</code>.</li>\n<li>Attribute:</li>\n<li><code>clientCapability: ClientCapabilityEnum [0..1]</code>.</li>\n<li><code>endToEndCallResponseTimeout: TimeValue [0..1]</code>.</li>\n<li>Assoziation zu <code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>): Rolle <code>+operation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Assoziationen zu <code>Field</code> (Spezialisierung von <code>AutosarDataPrototype</code>):</li>\n<li>Rolle <code>+getter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+setter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Komposition zu <code>TransformationComSpecProps</code> (Spezialisierung von <code>Describable</code>): Rolle <code>+transformationComSpecProps</code>, Multiplizität <code>0..*</code>.</li>\n<li><code>ClientServerOperation</code>:</li>\n<li>Attribut: <code>fireAndForget: Boolean [0..1]</code>.</li>\n<li><code>Field</code>:</li>\n<li>Attribute: <code>hasGetter: Boolean</code>, <code>hasNotifier: Boolean</code>, <code>hasSetter: Boolean</code>.</li>\n<li><code>ClientCapabilityEnum</code> («enumeration»):</li>\n<li>Literale: <code>willCall</code>, <code>wontCall</code>.</li>\n<li><code>TransformationComSpecProps</code>: Konfigurationscontainer für Transformations-Eigenschaften.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Spezifikation definiert Konfigurationsartefakte zur Design- und Generierungszeit: <code>ClientComSpec</code> deklariert die Client-Absicht bzw. -Fähigkeit bezüglich des Aufrufs von Operationen sowie der Getter- und Setter-Methoden von Fields (<code>willCall</code>/<code>wontCall</code>) und konfiguriert optional Fire-and-Forget-Semantik sowie transformationsbezogene Kommunikationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Attribut <code>endToEndCallResponseTimeout</code> definiert einen normativen Maximalzeitraum (<code>TimeValue</code>), innerhalb dessen der Client nach dem Absetzen eines synchronen/asynchronen Methodenaufrufs eine Antwort über die Kommunikationsschicht erwartet. Überwachung und Timeout-Behandlung sind im generierten Kommunikations-Proxy entsprechend zu berücksichtigen.</p>"}, {"id": "FIG-b0d03c969a615f34", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Kommunikationsspezifikationen auf der Empfängerseite (<code>ClientComSpec</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die strukturelle Einbettung von Port-Kommunikationsspezifikationen für clientseitige Interaktionen über Service-Schnittstellen (Operations und Fields).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Aggregiert über Komposition mit Rolle <code>+requiredComSpec</code> Instanzen von <code>RPortComSpec</code> (<code>0..*</code>).</li>\n<li><code>RPortComSpec</code> (abstrakt): Basisklasse für erforderliche Port-Kommunikationsspezifikationen.</li>\n<li><code>ClientComSpec</code>: Spezialisierung von <code>RPortComSpec</code>.</li>\n<li>Attribute:</li>\n<li><code>clientIntent: ClientIntentEnum [0..1]</code>.</li>\n<li><code>endToEndCallResponseTimeout: TimeValue [0..1]</code>.</li>\n<li>Assoziation zu <code>ClientServerOperation</code>: Rolle <code>+operation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Assoziationen zu <code>Field</code>:</li>\n<li>Rolle <code>+getter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+setter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Komposition zu <code>TransformationComSpecProps</code>: Rolle <code>+transformationComSpecProps</code>, Multiplizität <code>0..*</code>.</li>\n<li><code>ClientIntentEnum</code> («enumeration»):</li>\n<li>Literale: <code>willCall</code>, <code>wontCall</code>.</li>\n<li><code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>):</li>\n<li>Attribut: <code>fireAndForget: Boolean [0..1]</code>.</li>\n<li><code>Field</code> (Spezialisierung von <code>AutosarDataPrototype</code>):</li>\n<li>Attribute: <code>hasGetter: Boolean</code>, <code>hasNotifier: Boolean</code>, <code>hasSetter: Boolean</code>.</li>\n<li><code>TransformationComSpecProps</code> (Spezialisierung von <code>Describable</code>): Abstrakte Basisklasse für transformationsspezifische Kommunikationsparameter.</li>\n<li><code>EndToEndTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code>.</li>\n<li>Attribute:</li>\n<li><code>clearFromValidToInvalid: Boolean [0..1]</code></li>\n<li><code>disableEndToEndCheck: Boolean [0..1]</code></li>\n<li><code>disableEndToEndStateMachine: Boolean [0..1]</code></li>\n<li><code>maxDeltaCounter: PositiveInteger [0..1]</code></li>\n<li><code>maxErrorStateInit: PositiveInteger [0..1]</code></li>\n<li><code>maxErrorStateInvalid: PositiveInteger [0..1]</code></li>\n<li><code>maxErrorStateValid: PositiveInteger [0..1]</code></li>\n<li><code>minOkStateInit: PositiveInteger [0..1]</code></li>\n<li><code>minOkStateInvalid: PositiveInteger [0..1]</code></li>\n<li><code>minOkStateValid: PositiveInteger [0..1]</code></li>\n<li><code>windowSizeInit: PositiveInteger [0..1]</code></li>\n<li><code>windowSizeInvalid: PositiveInteger [0..1]</code></li>\n<li><code>windowSizeValid: PositiveInteger [0..1]</code></li>\n<li><code>UserDefinedTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code> für anwenderspezifische Transformer-Eigenschaften.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Spezifikation definiert Konfigurationsartefakte zur Design- und Generierungszeit: <code>ClientComSpec</code> deklariert die Client-Absicht bzw. -Fähigkeit bezüglich des Aufrufs von Operationen sowie der Getter- und Setter-Methoden von Fields (<code>willCall</code>/<code>wontCall</code>) und konfiguriert optional Fire-and-Forget-Semantik sowie transformationsbezogene Kommunikationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration der End-to-End-Absicherung (E2E) auf Client-Ebene erfolgt über <code>EndToEndTransformationComSpecProps</code>. Die Parameter steuern die Initialisierung, Fenstergrößen und Schwellwerte der E2E-Zustandsmaschine (<code>E2E State Machine</code>) sowie die Überprüfung eingehender Daten. <code>clientIntent</code> legt fest, ob der Client beabsichtigt, die entsprechende Operation oder den Field-Accessor aktiv aufzurufen, was der Optimierung von Ressourcen dient.</p>"}, {"id": "FIG-c4cd4620cacbc161", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Kommunikationsspezifikationen auf der Empfängerseite (<code>ClientComSpec</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die strukturelle Einbettung von Port-Kommunikationsspezifikationen für clientseitige Interaktionen über Service-Schnittstellen (Operations und Fields).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Aggregiert über Komposition mit Rolle <code>+requiredComSpec</code> Instanzen von <code>RPortComSpec</code> (<code>0..*</code>).</li>\n<li><code>RPortComSpec</code> (abstrakt): Basisklasse für erforderliche Port-Kommunikationsspezifikationen.</li>\n<li><code>ClientComSpec</code>: Spezialisierung von <code>RPortComSpec</code>.</li>\n<li>Attribute:</li>\n<li><code>clientIntent: ClientIntentEnum [0..1]</code>.</li>\n<li><code>endToEndCallResponseTimeout: TimeValue [0..1]</code>.</li>\n<li>Assoziation zu <code>ClientServerOperation</code>: Rolle <code>+operation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Assoziationen zu <code>Field</code>:</li>\n<li>Rolle <code>+getter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+setter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Komposition zu <code>TransformationComSpecProps</code>: Rolle <code>+transformationComSpecProps</code>, Multiplizität <code>0..*</code>.</li>\n<li><code>ClientIntentEnum</code> («enumeration»):</li>\n<li>Literale: <code>willCall</code>, <code>wontCall</code>.</li>\n<li><code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>):</li>\n<li>Attribut: <code>fireAndForget: Boolean [0..1]</code>.</li>\n<li><code>Field</code> (Spezialisierung von <code>AutosarDataPrototype</code>):</li>\n<li>Attribute: <code>hasGetter: Boolean</code>, <code>hasNotifier: Boolean</code>, <code>hasSetter: Boolean</code>.</li>\n<li><code>TransformationComSpecProps</code> (Spezialisierung von <code>Describable</code>): Abstrakte Basisklasse für transformationsspezifische Kommunikationsparameter.</li>\n<li><code>EndToEndTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code>.</li>\n<li>Attribute:</li>\n<li><code>clearFromValidToInvalid: Boolean [0..1]</code></li>\n<li><code>disableEndToEndCheck: Boolean [0..1]</code></li>\n<li><code>disableEndToEndStateMachine: Boolean [0..1]</code></li>\n<li><code>maxDeltaCounter: PositiveInteger [0..1]</code></li>\n<li><code>maxErrorStateInit: PositiveInteger [0..1]</code></li>\n<li><code>maxErrorStateInvalid: PositiveInteger [0..1]</code></li>\n<li><code>maxErrorStateValid: PositiveInteger [0..1]</code></li>\n<li><code>minOkStateInit: PositiveInteger [0..1]</code></li>\n<li><code>minOkStateInvalid: PositiveInteger [0..1]</code></li>\n<li><code>minOkStateValid: PositiveInteger [0..1]</code></li>\n<li><code>windowSizeInit: PositiveInteger [0..1]</code></li>\n<li><code>windowSizeInvalid: PositiveInteger [0..1]</code></li>\n<li><code>windowSizeValid: PositiveInteger [0..1]</code></li>\n<li><code>UserDefinedTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code> für anwenderspezifische Transformer-Eigenschaften.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Spezifikation definiert Konfigurationsartefakte zur Design- und Generierungszeit: <code>ClientComSpec</code> deklariert die Client-Absicht bzw. -Fähigkeit bezüglich des Aufrufs von Operationen sowie der Getter- und Setter-Methoden von Fields (<code>willCall</code>/<code>wontCall</code>) und konfiguriert optional Fire-and-Forget-Semantik sowie transformationsbezogene Kommunikationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration der End-to-End-Absicherung (E2E) auf Client-Ebene erfolgt über <code>EndToEndTransformationComSpecProps</code>. Die Parameter steuern die Initialisierung, Fenstergrößen und Schwellwerte der E2E-Zustandsmaschine (<code>E2E State Machine</code>) sowie die Überprüfung eingehender Daten. <code>clientIntent</code> legt fest, ob der Client beabsichtigt, die entsprechende Operation oder den Field-Accessor aktiv aufzurufen, was der Optimierung von Ressourcen dient.</p>"}, {"id": "FIG-40285b431dc4e9f5", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Kommunikationsspezifikationen auf der Empfängerseite (<code>ClientComSpec</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die strukturelle Einbettung von Port-Kommunikationsspezifikationen für clientseitige Interaktionen über Service-Schnittstellen (Operations und Fields).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Aggregiert über Komposition mit Rolle <code>+requiredComSpec</code> Instanzen von <code>RPortComSpec</code> (<code>0..*</code>).</li>\n<li><code>RPortComSpec</code> (abstrakt): Basisklasse für erforderliche Port-Kommunikationsspezifikationen.</li>\n<li><code>ClientComSpec</code>: Spezialisierung von <code>RPortComSpec</code>.</li>\n<li>Attribute:</li>\n<li><code>clientIntent: ClientIntentEnum [0..1]</code>.</li>\n<li><code>endToEndCallResponseTimeout: TimeValue [0..1]</code>.</li>\n<li>Assoziation zu <code>ClientServerOperation</code>: Rolle <code>+operation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Assoziationen zu <code>Field</code>:</li>\n<li>Rolle <code>+getter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+setter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Komposition zu <code>TransformationComSpecProps</code>: Rolle <code>+transformationComSpecProps</code>, Multiplizität <code>0..*</code>.</li>\n<li><code>ClientIntentEnum</code> («enumeration»):</li>\n<li>Literale: <code>willCall</code>, <code>wontCall</code>.</li>\n<li><code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>):</li>\n<li>Attribut: <code>fireAndForget: Boolean [0..1]</code>.</li>\n<li><code>Field</code> (Spezialisierung von <code>AutosarDataPrototype</code>):</li>\n<li>Attribute: <code>hasGetter: Boolean [0..1]</code>, <code>hasNotifier: Boolean [0..1]</code>, <code>hasSetter: Boolean [0..1]</code>.</li>\n<li><code>TransformationComSpecProps</code> (Spezialisierung von <code>Describable</code>): Basisklasse für Transformationsparameter.</li>\n<li><code>EndToEndTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code> mit Parametern zur E2E-Zustandsmaschine und Fehlerbehandlung (<code>clearFromValidToInvalid</code>, <code>disableEndToEndCheck</code>, <code>disableEndToEndStateMachine</code>, <code>maxDeltaCounter</code>, Fenstergrößen und Zustandsschwellwerte als <code>PositiveInteger [0..1]</code>).</li>\n<li><code>UserDefinedTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Spezifikation definiert Konfigurationsartefakte zur Design- und Generierungszeit: <code>ClientComSpec</code> deklariert die Client-Absicht bzw. -Fähigkeit bezüglich des Aufrufs von Operationen sowie der Getter- und Setter-Methoden von Fields (<code>willCall</code>/<code>wontCall</code>) und konfiguriert optional Fire-and-Forget-Semantik sowie transformationsbezogene Kommunikationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Durch die explizite Modellierung der Kardinalitäten <code>[0..1]</code> für <code>hasGetter</code>, <code>hasNotifier</code> und <code>hasSetter</code> in <code>Field</code> sind die entsprechenden Booleans optional. Manifest-Modellierer und Verifikationstools müssen das Fehlen dieser Attribute berücksichtigen (Standardwerte bzw. Schema-Defaults greifen).</p>"}, {"id": "FIG-23d49f62db5e442f", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Kommunikationsspezifikationen auf der Empfängerseite (<code>ClientComSpec</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die strukturelle Einbettung von Port-Kommunikationsspezifikationen für clientseitige Interaktionen über Service-Schnittstellen (Operations und Fields).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Aggregiert über Komposition mit Rolle <code>+requiredComSpec</code> Instanzen von <code>RPortComSpec</code> (<code>0..*</code>).</li>\n<li>Assoziation von <code>PortPrototype / AbstractRequiredPortPrototype</code> zu <code>Field</code> mit Stereotyp <code>«atpSplitable»</code>.</li>\n<li><code>RPortComSpec</code> (abstrakt): Basisklasse für erforderliche Port-Kommunikationsspezifikationen.</li>\n<li><code>ClientComSpec</code>: Spezialisierung von <code>RPortComSpec</code>.</li>\n<li>Attribute:</li>\n<li><code>clientIntent: ClientIntentEnum [0..1]</code>.</li>\n<li><code>endToEndCallResponseTimeout: TimeValue [0..1]</code>.</li>\n<li>Assoziation zu <code>ClientServerOperation</code>: Rolle <code>+operation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Assoziationen zu <code>Field</code>:</li>\n<li>Rolle <code>+setter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+getter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Komposition zu <code>TransformationComSpecProps</code>: Rolle <code>+transformationComSpecProps</code>, Multiplizität <code>0..*</code>.</li>\n<li><code>ClientIntentEnum</code> («enumeration»):</li>\n<li>Literale: <code>willCall</code>, <code>wontCall</code>.</li>\n<li><code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>):</li>\n<li>Attribut: <code>fireAndForget: Boolean [0..1]</code>.</li>\n<li><code>Field</code> (Spezialisierung von <code>AutosarDataPrototype</code>):</li>\n<li>Attribute: <code>hasGetter: Boolean [0..1]</code>, <code>hasNotifier: Boolean [0..1]</code>, <code>hasSetter: Boolean [0..1]</code>.</li>\n<li><code>TransformationComSpecProps</code> (Spezialisierung von <code>Describable</code>): Basisklasse für Transformationsparameter.</li>\n<li><code>EndToEndTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code> zur Spezifikation von E2E-Parametern (<code>clearFromValidToInvalid</code>, <code>disableEndToEndCheck</code>, <code>disableEndToEndStateMachine</code>, <code>maxDeltaCounter</code>, Fenstergrößen und Schwellenwerte).</li>\n<li><code>UserDefinedTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Spezifikation definiert Konfigurationsartefakte zur Design- und Generierungszeit: <code>ClientComSpec</code> deklariert die Client-Absicht bzw. -Fähigkeit bezüglich des Aufrufs von Operationen sowie der Getter- und Setter-Methoden von Fields (<code>willCall</code>/<code>wontCall</code>) und konfiguriert optional Fire-and-Forget-Semantik sowie transformationsbezogene Kommunikationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Stereotyp <code>«atpSplitable»</code> an der Assoziation zwischen <code>PortPrototype</code> und <code>Field</code> gestattet es, die Definitionen und Zuordnungen von Ports und Fields über mehrere ARXML-Dateien bzw. Manifest-Fragmente aufzuteilen und während der Modellaggregation zusammenzuführen.</p>"}, {"id": "FIG-92aaeefcbb62abab", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Kommunikationsspezifikationen auf der Empfängerseite (<code>ClientComSpec</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die strukturelle Einbettung von Port-Kommunikationsspezifikationen für clientseitige Interaktionen über Service-Schnittstellen (Operations und Fields).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Aggregiert über Komposition mit Rolle <code>+requiredComSpec</code> Instanzen von <code>RPortComSpec</code> (<code>0..*</code>).</li>\n<li>Assoziation von <code>PortPrototype / AbstractRequiredPortPrototype</code> zu <code>Field</code> mit Stereotyp <code>«atpSplitable»</code>.</li>\n<li><code>RPortComSpec</code> (abstrakt): Basisklasse für erforderliche Port-Kommunikationsspezifikationen.</li>\n<li><code>ClientComSpec</code>: Spezialisierung von <code>RPortComSpec</code>.</li>\n<li>Attribute:</li>\n<li><code>clientIntent: ClientIntentEnum [0..1]</code>.</li>\n<li><code>endToEndCallResponseTimeout: TimeValue [0..1]</code>.</li>\n<li>Assoziation zu <code>ClientServerOperation</code>: Rolle <code>+operation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Assoziationen zu <code>Field</code>:</li>\n<li>Rolle <code>+setter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+getter</code>, Multiplizität <code>0..1</code>.</li>\n<li>Komposition zu <code>TransformationComSpecProps</code>: Rolle <code>+transformationComSpecProps</code>, Multiplizität <code>0..*</code>.</li>\n<li><code>ClientIntentEnum</code> («enumeration»):</li>\n<li>Literale: <code>willCall</code>, <code>wontCall</code>.</li>\n<li><code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>):</li>\n<li>Attribut: <code>fireAndForget: Boolean [0..1]</code>.</li>\n<li><code>Field</code> (Spezialisierung von <code>AutosarDataPrototype</code>):</li>\n<li>Attribute: <code>hasGetter: Boolean [0..1]</code>, <code>hasNotifier: Boolean [0..1]</code>, <code>hasSetter: Boolean [0..1]</code>.</li>\n<li><code>TransformationComSpecProps</code> (Spezialisierung von <code>Describable</code>): Basisklasse für Transformationsparameter.</li>\n<li><code>EndToEndTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code> zur Spezifikation von E2E-Parametern (<code>clearFromValidToInvalid</code>, <code>disableEndToEndCheck</code>, <code>disableEndToEndStateMachine</code>, <code>maxDeltaCounter</code>, Fenstergrößen und Schwellenwerte).</li>\n<li><code>UserDefinedTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Spezifikation definiert Konfigurationsartefakte zur Design- und Generierungszeit: <code>ClientComSpec</code> deklariert die Client-Absicht bzw. -Fähigkeit bezüglich des Aufrufs von Operationen sowie der Getter- und Setter-Methoden von Fields (<code>willCall</code>/<code>wontCall</code>) und konfiguriert optional Fire-and-Forget-Semantik sowie transformationsbezogene Kommunikationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Stereotyp <code>«atpSplitable»</code> an der Assoziation zwischen <code>PortPrototype</code> und <code>Field</code> gestattet es, die Definitionen und Zuordnungen von Ports und Fields über mehrere ARXML-Dateien bzw. Manifest-Fragmente aufzuteilen und während der Modellaggregation zusammenzuführen.</p>"}, {"id": "FIG-c1b9e7bdf369d23e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Kommunikationsspezifikationen auf der Empfängerseite (<code>ClientComSpec</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die strukturelle Einbettung von Port-Kommunikationsspezifikationen für clientseitige Interaktionen über Service-Schnittstellen (Operations und Fields).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Aggregiert über Komposition mit Rolle <code>+requiredComSpec</code> Instanzen von <code>RPortComSpec</code> (<code>0..*</code>).</li>\n<li>Assoziation von <code>PortPrototype / AbstractRequiredPortPrototype</code> zu <code>Field</code> mit Stereotyp <code>«atpSplitable»</code>.</li>\n<li><code>RPortComSpec</code> (abstrakt): Basisklasse für erforderliche Port-Kommunikationsspezifikationen.</li>\n<li><code>ClientComSpec</code>: Spezialisierung von <code>RPortComSpec</code>.</li>\n<li>Attribute:</li>\n<li><code>clientIntent: ClientIntentEnum [0..1]</code>.</li>\n<li><code>endToEndCallResponseTimeout: TimeValue [0..1]</code>.</li>\n<li>Assoziation zu <code>ClientServerOperation</code>: Rolle <code>+operation</code>, Multiplizität <code>0..1</code>, mit Stereotyp <code>«atpIdentityContributor»</code>.</li>\n<li>Assoziationen zu <code>Field</code>:</li>\n<li>Rolle <code>+setter</code>, Multiplizität <code>0..1</code>, mit Stereotyp <code>«atpIdentityContributor»</code>.</li>\n<li>Rolle <code>+getter</code>, Multiplizität <code>0..1</code>, mit Stereotyp <code>«atpIdentityContributor»</code>.</li>\n<li>Komposition zu <code>TransformationComSpecProps</code>: Rolle <code>+transformationComSpecProps</code>, Multiplizität <code>0..*</code>, mit Stereotyp <code>«atpSplitable»</code>.</li>\n<li><code>ClientIntentEnum</code> («enumeration»):</li>\n<li>Literale: <code>willCall</code>, <code>wontCall</code>.</li>\n<li><code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>):</li>\n<li>Attribut: <code>fireAndForget: Boolean [0..1]</code>.</li>\n<li><code>Field</code> (Spezialisierung von <code>AutosarDataPrototype</code>):</li>\n<li>Attribute: <code>hasGetter: Boolean [0..1]</code>, <code>hasNotifier: Boolean [0..1]</code>, <code>hasSetter: Boolean [0..1]</code>.</li>\n<li><code>TransformationComSpecProps</code> (Spezialisierung von <code>Describable</code>): Basisklasse für Transformationsparameter.</li>\n<li><code>EndToEndTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code> zur Spezifikation von E2E-Parametern (<code>clearFromValidToInvalid</code>, <code>disableEndToEndCheck</code>, <code>disableEndToEndStateMachine</code>, <code>maxDeltaCounter</code>, Fenstergrößen und Schwellenwerte).</li>\n<li><code>UserDefinedTransformationComSpecProps</code>: Spezialisierung von <code>TransformationComSpecProps</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Spezifikation definiert Konfigurationsartefakte zur Design- und Generierungszeit: <code>ClientComSpec</code> deklariert die Client-Absicht bzw. -Fähigkeit bezüglich des Aufrufs von Operationen sowie der Getter- und Setter-Methoden von Fields (<code>willCall</code>/<code>wontCall</code>) und konfiguriert optional Fire-and-Forget-Semantik sowie transformationsbezogene Kommunikationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Stereotyp <code>«atpSplitable»</code> an der Assoziation zwischen <code>PortPrototype</code> und <code>Field</code> sowie an der Komposition von <code>ClientComSpec</code> zu <code>TransformationComSpecProps</code> (<code>+transformationComSpecProps</code>) gestattet das Aufteilen und Zusammenführen dieser Modellelemente über mehrere ARXML-Dateien bzw. Manifest-Fragmente. Das Stereotyp <code>«atpIdentityContributor»</code> an den Assoziationen <code>+operation</code>, <code>+setter</code> und <code>+getter</code> kennzeichnet diese Zielreferenzen als identitätsstiftend für die jeweilige Instanz von <code>ClientComSpec</code>.</p>"}], "trans": [{"from": "FIG-113e5ae0d191d2da", "to": "FIG-bb6b3cfcb85a396b", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>ClientComSpec</code>: Typangabe des Attributs <code>clientCapability</code> typografisch vereinheitlicht (Doppelpunkt ohne vorangehendes Leerzeichen als <code>: </code> statt <code> :</code>).</li>\n<li><code>ClientServerOperation</code>: Typangabe des Attributs <code>fireAndForget</code> typografisch vereinheitlicht (Doppelpunkt ohne vorangehendes Leerzeichen als <code>: </code> statt <code> :</code>).</li>\n<li><code>Field</code>: Typangaben der Attribute <code>hasGetter</code>, <code>hasNotifier</code> und <code>hasSetter</code> typografisch vereinheitlicht (Doppelpunkt ohne vorangehendes Leerzeichen als <code>: </code> statt <code> :</code>).</li>\n</ul>"}, {"from": "FIG-bb6b3cfcb85a396b", "to": "FIG-b5a60ae4c9d07f88", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ClientComSpec</code>: Attribut <code>endToEndCallResponseTimeout: TimeValue [0..1]</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-b5a60ae4c9d07f88", "to": "FIG-b0d03c969a615f34", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ClientComSpec</code>: Attribut <code>clientCapability: ClientCapabilityEnum [0..1]</code> ersetzt durch <code>clientIntent: ClientIntentEnum [0..1]</code>.</li>\n<li><code>ClientCapabilityEnum</code>: Enumeration ersetzt durch <code>ClientIntentEnum</code> mit den unveränderten Literalen <code>willCall</code> und <code>wontCall</code>.</li>\n<li><code>TransformationComSpecProps</code>: Spezialisierungen <code>EndToEndTransformationComSpecProps</code> und <code>UserDefinedTransformationComSpecProps</code> als Subklassen per Generalisierungspfeil ergänzt.</li>\n<li><code>EndToEndTransformationComSpecProps</code>: Neu eingeführte Klasse mit den Attributen <code>clearFromValidToInvalid: Boolean [0..1]</code>, <code>disableEndToEndCheck: Boolean [0..1]</code>, <code>disableEndToEndStateMachine: Boolean [0..1]</code>, <code>maxDeltaCounter: PositiveInteger [0..1]</code>, <code>maxErrorStateInit: PositiveInteger [0..1]</code>, <code>maxErrorStateInvalid: PositiveInteger [0..1]</code>, <code>maxErrorStateValid: PositiveInteger [0..1]</code>, <code>minOkStateInit: PositiveInteger [0..1]</code>, <code>minOkStateInvalid: PositiveInteger [0..1]</code>, <code>minOkStateValid: PositiveInteger [0..1]</code>, <code>windowSizeInit: PositiveInteger [0..1]</code>, <code>windowSizeInvalid: PositiveInteger [0..1]</code> und <code>windowSizeValid: PositiveInteger [0..1]</code>.</li>\n<li><code>UserDefinedTransformationComSpecProps</code>: Neu eingeführte Klasse als Spezialisierung von <code>TransformationComSpecProps</code> ohne eigene Attribute.</li>\n<li>Diagrammlayout: Klassenanordnung grundlegend restrukturiert (<code>Field</code> oberhalb von <code>ClientComSpec</code>, <code>TransformationComSpecProps</code> nach rechts verlagert).</li>\n</ul>"}, {"from": "FIG-b0d03c969a615f34", "to": "FIG-c4cd4620cacbc161", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c4cd4620cacbc161", "to": "FIG-40285b431dc4e9f5", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Field</code>: Multiplizitäten der Attribute <code>hasGetter</code>, <code>hasNotifier</code> und <code>hasSetter</code> explizit von implizit <code>[1]</code> auf optional <code>[0..1]</code> geändert.</li>\n<li>Diagrammlayout: Position von <code>Field</code> und der Enumeration <code>ClientIntentEnum</code> leicht angepasst.</li>\n</ul>"}, {"from": "FIG-40285b431dc4e9f5", "to": "FIG-23d49f62db5e442f", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziation <code>PortPrototype / AbstractRequiredPortPrototype</code> zu <code>Field</code>: Neu modellierte Kompositions- bzw. Referenzbeziehung mit Stereotyp <code>«atpSplitable»</code>.</li>\n<li><code>TransformationComSpecProps</code>: Generalisierungspfeile für <code>EndToEndTransformationComSpecProps</code> und <code>UserDefinedTransformationComSpecProps</code> separat statt zusammengeführt modelliert.</li>\n<li><code>ClientComSpec</code>: Rollenbezeichnungen <code>+getter</code> und <code>+setter</code> zu <code>Field</code> horizontal vertauscht.</li>\n</ul>"}, {"from": "FIG-23d49f62db5e442f", "to": "FIG-92aaeefcbb62abab", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>ClientIntentEnum</code>: Abschnittskopf <code>literals</code> über den Literalen ergänzt.</li>\n</ul>"}, {"from": "FIG-92aaeefcbb62abab", "to": "FIG-c1b9e7bdf369d23e", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziation <code>ClientComSpec</code> zu <code>ClientServerOperation</code> (<code>+operation</code>): Stereotyp <code>«atpIdentityContributor»</code> ergänzt.</li>\n<li>Assoziation <code>ClientComSpec</code> zu <code>Field</code> (<code>+setter</code>): Stereotyp <code>«atpIdentityContributor»</code> ergänzt.</li>\n<li>Assoziation <code>ClientComSpec</code> zu <code>Field</code> (<code>+getter</code>): Stereotyp <code>«atpIdentityContributor»</code> ergänzt.</li>\n<li>Komposition von <code>ClientComSpec</code> zu <code>TransformationComSpecProps</code> (<code>+transformationComSpecProps</code>): Stereotyp <code>«atpSplitable»</code> ergänzt.</li>\n</ul>"}]};
